    if not resources:
        # Keep moving to reduce being cornered; prefer moving toward midline relative to opponent
        mx = w // 2
        my = h // 2
        best = None
        bestv = -10**9
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny) or (nx, ny) in obstacles:
                continue
            v = -(abs(nx - mx) + abs(ny - my)) - 0.3 * near_obst(nx, ny)
            if v > bestv:
                bestv = v
                best = (dx, dy)
        return list(best if best is not None else (0, 0))

    # Pick a target that we can reach earlier than opponent (with obstacle-aware slight bias)
    def dist(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    def target_value(tx, ty, px, py):
        ds = dist(px, py, tx, ty)
        do = dist(ox, oy, tx, ty)
        # Favor resources we are closer to; if tie, prefer those farther from opponent and closer to us.
        return (do - ds, -ds)

    # Deterministic: choose best target based on current positions.
    best_t = None
    best_tv = None
    for tx, ty in resources:
        tv = target_value(tx, ty, sx, sy)
        if best_t is None or tv > best_tv:
            best_t = (tx, ty)
            best_tv = tv

    tx, ty = best_t

