    best_move = (0, 0)
    best_score = -10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny) or (nx, ny) in obstacles:
            continue
        ds_next = dist(nx, ny, tx, ty)
        ds_now = dist(sx, sy, tx, ty)
        do = dist(ox, oy, tx, ty)
        # If opponent is already closer, switch pressure toward resources that reduce our lead less;
        # this helps against sweep-like behavior by preventing being chased into a losing lane.
        lead_now = do - ds_now
        lead_next = do - ds_next
        opp_escape = 0
        # Encourage moves that also increase distance to opponent a bit (lane denial).
        opp_escape = -0.15 * dist(nx, ny, ox, oy)

        progress = (ds_now - ds_next)  # positive if closer
        # Prefer not to get stuck near obstacles.
        obst_pen = 0.8 * near_obst(nx, ny) + (1.2 if (nx, ny) in obstacles else 0)
        # If we're behind, focus on minimizing ds_next; otherwise maximize progress.
        if lead_now <= 0:
            v = (-ds_next, lead_next, progress, opp_escape)
        else:
            v = (progress, lead_next, -ds_next, opp_escape)
        score = (v[0] * 1000 + v[1] * 10 + v[2] + v[3]) - obst_pen
        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

